+import { buildBriefQuestions, buildBriefState, readBriefAssessment, type BriefAssessment } from "./brief-coach";
+import { buildTriageQuestions, buildTriageState, readTriage, splitPassages, type TriagedPassage } from "./passage-triage";
+import { runWritingLens, WRITING_LENSES, type WritingLensId, type WritingLensResult, type WritingLensInput } from "./writing-lenses";
+import type { SystemOneAnswer, SystemOneQuestion, SystemOneUsage } from "./system-one";
+
+export interface LiveReview {
+  folioId: string;
+  fingerprint: string;
+  at: number;
+  rubric: RubricResult | null;
+  brief: BriefAssessment | null;
+  passages: TriagedPassage[];
+  coverage: string;
+  lenses: Partial<Record<WritingLensId, WritingLensResult>>;
+}
+export interface LiveReviewSnapshot {
+  folioId: string | null;
+  status: "waiting" | "reading" | "current" | "paused" | "offline" | "unavailable";
+  message: string;
+  result: LiveReview | null;
+}
+type Response = { ok: boolean; model?: string; answers?: Record<string, unknown>; usage?: SystemOneUsage; error?: string };
+let snapshot: LiveReviewSnapshot = { folioId: null, status: "waiting", message: "Review updates after your draft is saved.", result: null };
+export const liveReviewSnapshot = () => snapshot;
+export const liveReviewKey = (folioId: string) => `live-review:${folioId}`;
+
+function publish(next: LiveReviewSnapshot) {
+  snapshot = next;
+  window.dispatchEvent(new CustomEvent("twyne:live-review", { detail: next }));
+}
+
+/** One owner per editor workspace; independent of which board panel is visible. */
+export function startLiveReview(client: ConvexClient | null, folioId: string): () => void {
+  let stopped = false;
+  let generation = 0;
+  let running = false;
+  let pending = false;
+  let timer: ReturnType<typeof setTimeout> | undefined;
+  let lastStarted = 0;
+  let failures = 0;
+  // Cache semantic requests, not weights or presentation settings. Bounded to this folio session.
+  const cache = new Map<string, Response>();
+  const lensCache = new Map<string, WritingLensResult>();
+  const setStatus = (status: LiveReviewSnapshot["status"], message: string) => {
+    if (!stopped) publish({ ...snapshot, folioId, status, message });
+  };
+  publish({ folioId, status: "waiting", message: "Review updates after your draft is saved.", result: null });
+  void loadMetaFromIdb<LiveReview>(liveReviewKey(folioId)).then((result) => {
+    if (!stopped && !snapshot.result && result?.folioId === folioId)
+      publish({ ...snapshot, result });
+  });
+
+  const schedule = () => {
+    if (stopped) return;
+    generation++;
+    pending = true;
+    clearTimeout(timer);
+    if (!running) {
+      setStatus("waiting", "Waiting for a pause in writing…");
+      timer = setTimeout(() => void run(), Math.max(2500, lastStarted + 30_000 - Date.now()));
+    }
+  };
+  const run = async () => {
+    if (stopped || running) return;
+    pending = false;
+    if (document.hidden) return;
+    if (navigator.onLine === false) {
+      setStatus("offline", "Saved locally. Review will resume when you reconnect.");
+      return;
+    }
+    if ((await loadMetaFromIdb<boolean>("live-review-enabled")) === false) {
+      setStatus("paused", "Automatic review is paused.");
+      return;
+    }
+    if (stopped) return;
+    if (!client) {
+      setStatus("unavailable", "Connect your account to keep the review up to date.");
+      return;
+    }
+    running = true;
+    lastStarted = Date.now();
+    const token = generation;
+    const current = () => !stopped && token === generation;
+    let calls = 0;
+    try {
+      const [html, brief, specs, notebook, revisions, notes] = await Promise.all([
+        loadFolioContentFromIdb(folioId), loadBriefFromIdb(folioId), loadCriteriaSpecs(folioId),
+        loadWritingToolsNotebook(folioId), loadRevisionHistory(folioId), loadPersonaNotesLocally(folioId),
+      ]);
+      if (!current()) return;
+      const draft = paragraphTextFromHtml(html);
+      const plain = htmlToPlainText(html);
+      if (!draftReadiness(plain, MIN_RUBRIC_WORDS).ok) {
+        publish({ folioId, status: "waiting", message: `Review begins at ${MIN_RUBRIC_WORDS} words. Your draft is saved as usual.`, result: null });
+        return;
+      }
+      const fresh = async () => {
+        if (!current() || (await loadActiveFolioIdFromIdb()) !== folioId) return false;
+        let latest: string;
+        try { latest = requestActiveDraftSnapshot(folioId); }
+        catch { latest = await loadFolioContentFromIdb(folioId); }
+        return current() && htmlToPlainText(latest) === plain;
+      };
+      if (!(await fresh())) return;
+      setStatus("reading", "Reading the saved draft…");
+      const ask = async (input: { state: Record<string, unknown>; questions: Record<string, SystemOneQuestion> }): Promise<Response> => {
+        if (!current()) throw new Error("superseded");
+        const key = await rubricDraftFingerprint(JSON.stringify(input));
+        const cached = cache.get(key);
+        if (cached) return cached;
+        if (++calls > 32) throw new Error("budget");
+        const response = await client.action(api.systemOne.ask, {
+          state: Object.fromEntries(Object.entries(input.state).map(([key, value]) => [key, typeof value === "string" ? value : JSON.stringify(value)])),
+          questions: input.questions,
+        }) as Response;
+        if (!response.ok || !response.answers) throw new Error("unavailable");
+        if (Object.keys(input.questions).some((id) => !response.answers?.[id])) throw new Error("incomplete");
+        cache.set(key, response);
+        if (cache.size > 64) cache.delete(cache.keys().next().value!);
+        return response;
+      };
+      // Grade the whole draft only when it fits. A bounded excerpt must never earn a whole-piece grade.
+      const bounded = draft.slice(0, 40_000);
+      const candidates = splitPassages(bounded).slice(0, 12);
+      const rubricQuestions = draft.length <= 40_000 ? buildRubricQuestions(specs) : {};
+      const questions = {
+        ...Object.fromEntries(Object.entries(rubricQuestions).map(([id, q]) => [`rubric_${id}`, q])),
+        ...buildTriageQuestions(candidates),
+      };
+      const state = { ...buildTriageState(candidates, bounded), audience: brief?.answers.audience ?? "", goal: brief?.answers.goal ?? "" };
+      const answers: Record<string, SystemOneAnswer> = {};
+      let model = "";
+      const usage = { input_tokens: 0, output_tokens: 0 };
+      const entries = Object.entries(questions);
+      for (let i = 0; i < entries.length; i += 64) {
+        const response = await ask({ state, questions: Object.fromEntries(entries.slice(i, i + 64)) });
+        Object.assign(answers, response.answers);
+        model = response.model ?? "unknown";
+        usage.input_tokens += response.usage?.input_tokens ?? 0;
+        usage.output_tokens += response.usage?.output_tokens ?? 0;
+      }
+      const fingerprint = await rubricDraftFingerprint(plain);
+      const rubric = Object.keys(rubricQuestions).length ? judgementRubricResult({
+        folioId, fingerprint, specs, staticScore: scoreStaticFeatures(plain),
+        grade: readRubricAnswers(Object.fromEntries(Object.entries(answers).filter(([id]) => id.startsWith("rubric_")).map(([id, answer]) => [id.slice(7), answer])), { model, usage }),
+      }) : null;
+      let assessment: BriefAssessment | null = null;
+      if (brief) {
+        const response = await ask({ state: buildBriefState(brief), questions: buildBriefQuestions(brief) });
+        assessment = readBriefAssessment(brief, response.answers as Record<string, SystemOneAnswer>);
+      }
+      const result: LiveReview = {
+        folioId, fingerprint, at: Date.now(), rubric, brief: assessment,
+        passages: readTriage(candidates, answers),
+        coverage: `${candidates.length} passages checked for attention${draft.length > 40_000 ? "; opening 40,000 characters only, no whole-draft grade" : ""}.`,
+        lenses: {},
+      };
+      const history = revisions.map((revision) => ({ id: revision.id, text: paragraphTextFromHtml(revision.html) }));
+      const previousDraft = history.find((revision) => revision.text !== draft)?.text;
+      for (const { id } of WRITING_LENSES) {
+        if (!current()) return;
+        const input: WritingLensInput = { draft, audience: notebook.audience || brief?.answers.audience,
+          ...(id === "revision" || id === "voice" ? { previousDraft } : {}),
+          ...(id === "voice" ? { voiceSamples: notebook.voiceSamples } : {}),
+          ...(id === "scraps" ? { scraps: notebook.scraps } : {}),
+          ...(id === "room" ? { notes: notes.slice(-8).map((note, index) => ({ id: note.noteId ?? String(index), text: note.feedback, author: note.personaName })) } : {}),
+          ...(id === "circling" ? { revisions: [...history].reverse() } : {}),
+          ...(id === "research" ? { sources: notebook.sources } : {}),
+          ...(id === "promises" ? { intentionalPromises: notebook.intentionalPromises } : {}),
+        };
+        const key = await rubricDraftFingerprint(JSON.stringify([id, input]));
+        if (id === "research" && notebook.sources.some((pair) => !draft.includes(pair.claim))) {
+          result.lenses[id] = { status: "missing-input", findings: [], coverage: "No source pairs sent.", notice: "Update saved claims to match the current draft before checking research drift." };
+        } else {
+          const lens = lensCache.get(key) ?? await runWritingLens(id, input, ask);
+          result.lenses[id] = lens;
+          if (lens.status !== "unavailable") lensCache.set(key, lens);
+          if (lensCache.size > 32) lensCache.delete(lensCache.keys().next().value!);
+        }
+      }
+      if (!(await fresh())) return;
+      // Keep the authored review assembled from typed findings; no fictional persona metrics or generated essay.
+      await saveMetaToIdb(liveReviewKey(folioId), result);
+      if (!current()) return;
+      if (rubric) {
+        await saveRubricResultToIdb(rubric, folioId);
+        if (!current()) return;
+        await appendRubricHistory({ folioId, at: rubric.timestamp, overall: rubric.overallScore, grade: rubric.overallGrade, targetFit: rubric.targetFit, scoringMethod: "judgement", perCriterion: Object.fromEntries(rubric.criteria.map((c) => [c.id, c.score])) }, folioId);
+      }
+      if (!current()) return;
+      failures = 0;
+      publish({ folioId, status: "current", message: "Review is up to date with the saved draft.", result });
+      window.dispatchEvent(new CustomEvent("twyne:rubric-updated", { detail: { folioId } }));
+    } catch {
+      if (current()) {
+        failures++;
+        setStatus("unavailable", "Review is temporarily unavailable. Your draft is saved; another reading will be tried shortly.");
+        timer = setTimeout(schedule, Math.min(300_000, 30_000 * 2 ** Math.min(failures, 4)));
+      }
+    } finally {
+      running = false;
+      if (pending && !stopped) schedule();
+    }
+  };
+  const onSave = (event: Event) => {
+    const saved = (event as CustomEvent<{ folioId?: string }>).detail;
+    if (!saved?.folioId || saved.folioId === folioId) schedule();
+  };
+  const onContent = () => {
+    // Invalidate immediately, even before persistence completes.
+    generation++;
+    if (snapshot.status === "current") setStatus("waiting", "Draft changed. Review will update after saving.");
+  };
+  const onResume = () => { if (!document.hidden) schedule(); };
+  const events = ["twyne:draft-saved", "twyne:criteria-changed", "twyne:writing-material-changed", "twyne:background-room-notes", "twyne:live-review-setting", "twyne:remote-sync"];
+  events.forEach((event) => window.addEventListener(event, onSave));
+  window.addEventListener("twyne:content", onContent);
+  window.addEventListener("online", onResume);
+  document.addEventListener("visibilitychange", onResume);
+  schedule();
+  return () => {
+    stopped = true;
+    generation++;
+    clearTimeout(timer);
+    events.forEach((event) => window.removeEventListener(event, onSave));
+    window.removeEventListener("twyne:content", onContent);
+    window.removeEventListener("online", onResume);
+    document.removeEventListener("visibilitychange", onResume);
+  };
+}
