+
+const key = new PluginKey<DecorationSet>("quickReview");
+const OPTIONS = ["No clear issue", "Needs context", "Check evidence", "Possible repetition", "Meaning is unclear"];
+const COPY: Record<string, string> = {
+  "Needs context": "A reader may need a person, term, or connection explained here. Check what the preceding paragraph has established.",
+  "Check evidence": "This passage may make a claim that needs support. Check the claim against a source you trust.",
+  "Possible repetition": "This may repeat a point already made nearby. Check whether the repetition adds emphasis or new meaning.",
+  "Meaning is unclear": "The connection or reference in this passage may be unclear. Read it with the preceding paragraph to see where the meaning slips.",
+};
+
+export const QuickReview = Extension.create({
+  name: "quickReview",
+  addProseMirrorPlugins() {
+    return [new Plugin<DecorationSet>({
+      key,
+      state: {
+        init: () => DecorationSet.empty,
+        // These are ephemeral decorations, never marks in the saved manuscript.
+        apply: (tr, previous) => tr.getMeta(key) ?? (tr.docChanged ? DecorationSet.empty : previous),
+      },
+      props: { decorations: (state) => key.getState(state) },
+    })];
+  },
+});
+
+/** Latest changed paragraph first. No whole-document scan or panel mount on the critical path. */
+export function startQuickReview(editor: Editor, getClient: () => ConvexClient | null | undefined, folioId: string, brief: ProjectBrief | null): () => void {
+  let timer: ReturnType<typeof setTimeout> | undefined;
+  let stopped = false;
+  let generation = 0;
+  let running = false;
+  let pending = false;
+  let enabled = true;
+  let backoffUntil = 0;
+  let popover: HTMLElement | null = null;
+  const calls: number[] = [];
+  const cache = new Map<string, { label: string; tentative: boolean } | null>();
+  const notify = (label: string, detail = "") => window.dispatchEvent(new CustomEvent("twyne:quick-review", { detail: { folioId, label, detail } }));
+  const clear = () => {
+    popover?.remove();
+    popover = null;
+    if (!editor.isDestroyed) editor.view.dispatch(editor.state.tr.setMeta(key, DecorationSet.empty).setMeta("addToHistory", false));
+  };
+  const draw = (from: number, to: number, finding: { label: string; tentative: boolean } | null) => {
+    if (!finding) { notify("No clear issue in this passage"); return; }
+    const label = `${finding.tentative ? "Possibly: " : ""}${finding.label}`;
+    const detail = COPY[finding.label];
+    notify(label, detail);
+    const decorations = DecorationSet.create(editor.state.doc, [
