+export function readProviderCallback(attempt: ProviderLinkAttempt, userId: string, url: URL): {code: string; verifier: string} {
+  if (attempt.userId !== userId || !Number.isFinite(attempt.expiresAt) || Date.now() >= attempt.expiresAt || url.origin !== attempt.origin || url.pathname !== "/settings/" || url.hash || url.searchParams.has("error") || url.searchParams.getAll("state").length !== 1 || url.searchParams.get("state") !== attempt.state || url.searchParams.getAll("code").length !== 1 || !url.searchParams.get("code")) {
